sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
uniform float amzp_radius;
uniform float amzp_falloff1;
uniform float amzp_falloff2;
uniform float amzp_bright;
uniform float amzp_angle;
uniform float2 amzp_center;
uniform float amzp_noiseAmt;
uniform float amzp_animGrain;
uniform float amzp_blendMode;
uniform float amzp_alphab;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float4 layerClamp(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float th1(float x) { x = clamp(x, -15.0, 15.0); float e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float3 th3(float3 x) { x = clamp(x, -15.0, 15.0); float3 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float4 th4(float4 x) { x = clamp(x, -15.0, 15.0); float4 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float2x2 rot2(float a) { float c = cos(a), s = sin(a); return float2x2(c, -s, s, c); }
    float TT() { return (amzp_autop>0.5) ? amzp_progress + time * (amzp_aSpeed * 0.5) : amzp_progress; }
    float rnd(float2 p) { return fract(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453); }
    float3 rgb2hsv(float3 c) {
        float4 k = float4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
        float4 p = mix(float4(c.bg, k.wz), float4(c.gb, k.xy), step(c.b, c.g));
        float4 q = mix(float4(p.xyw, c.r), float4(c.r, p.yzx), step(p.x, c.r));
        float d = q.x - min(q.w, q.y);
        return float3(abs(q.z + (q.w - q.y) / (6.0 * d + 1e-10)), d / (q.x + 1e-10), q.x);
    }
    float3 hsv2rgb(float3 c) { float4 k = float4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0); float3 p = abs(fract(c.xxx + k.xyz) * 6.0 - k.www); return c.z * mix(k.xxx, clamp(p - k.xxx, 0.0, 1.0), c.y); }
    float3 blendC(float3 b, float3 g, int m) {
        if (m == 0) return g;
        if (m == 1) return b * g;
        if (m == 2) return 1.0 - (1.0 - b) * (1.0 - g);
        if (m == 3) return mix(2.0 * b * g, 1.0 - 2.0 * (1.0 - b) * (1.0 - g), step(0.5, b));
        if (m == 4) { float3 hb = rgb2hsv(b), hg = rgb2hsv(g); return hsv2rgb(float3(hg.x, hg.y, hb.z)); }
        if (m == 5) return max(b, g);
        if (m == 6) return clamp(b / max(1.0 - g, 1e-6), 0.0, 1.0);
        if (m == 7) return clamp(1.0 - (1.0 - b) / max(g, 1e-6), 0.0, 1.0);
        if (m == 8) return clamp(b + g, 0.0, 1.0);
        if (m == 9) return clamp(b + g - 1.0, 0.0, 1.0);
        if (m == 10) return clamp(b + 2.0 * g - 1.0, 0.0, 1.0);
        if (m == 11) return min(b, g);
        if (m == 12) return clamp((1.0 - 2.0 * g) * b * b + 2.0 * g * b, 0.0, 1.0);
        if (m == 13) return mix(2.0 * b * g, 1.0 - 2.0 * (1.0 - b) * (1.0 - g), step(0.5, g));
        if (m == 14) return mix(clamp(1.0 - (1.0 - b) / max(2.0 * g, 1e-6), 0.0, 1.0), clamp(b / max(2.0 * (1.0 - g), 1e-6), 0.0, 1.0), step(0.5, g));
        if (m == 15) return mix(min(b, 2.0 * g), max(b, 2.0 * g - 1.0), step(0.5, g));
        if (m == 16) { float3 hb = rgb2hsv(b), hg = rgb2hsv(g); return hsv2rgb(float3(hg.x, hb.y, hb.z)); }
        if (m == 17) return abs(b - g);
        if (m == 18) { float3 hb = rgb2hsv(b), hg = rgb2hsv(g); return hsv2rgb(float3(hb.x, hb.y, hg.z)); }
        if (m == 19) { float3 hb = rgb2hsv(b), hg = rgb2hsv(g); return hsv2rgb(float3(hb.x, hg.y, hb.z)); }
        if (m == 20) return clamp(b / max(g, 1e-6), 0.0, 1.0);
        return clamp(b - g, 0.0, 1.0);
    }
    void nmMain() {
        float2 W = layer;
        float4 orig = layerAt(amzLayerNorm());
        float2 uv = amzLayerNorm();
        float asp = W.x / W.y;
        float a = radians(amzp_angle) + TT();
        float2 ctr = float2(0.5) + float2(amzp_center.x, -amzp_center.y) * pxs() / W;
        float2 cA = ctr * float2(asp, 1.0);
        float2 p1 = cA + float2(cos(a), sin(a)) * amzp_radius;
        float2 p2 = cA - float2(cos(a), sin(a)) * amzp_radius;
        float2 u = uv * float2(asp, 1.0);
        float3 grad = amzp_color1.rgb * exp(-distance(u, p1) * amzp_falloff1) + amzp_color2.rgb * exp(-distance(u, p2) * amzp_falloff2);
        grad = clamp(grad * amzp_bright, 0.0, 1.0);
        float gt = (amzp_animGrain>0.5) ? floor(time * 24.0) * 1.37 : 0.0;
        grad += (rnd(uv * W + gt) - 0.5) * 2.0 * amzp_noiseAmt;
        grad = clamp(grad, 0.0, 1.0);
        float4 src = orig;
        float3 base = src.a > 0.0001 ? src.rgb / src.a : float3(0.0);
        float3 comp = blendC(base, grad, int(amzp_blendMode));
        float3 o = mix(base, comp, amzp_alphab);
        float4 R = float4(clamp(o, 0.0, 1.0) * src.a, src.a);
        amzOutput = R;
    }
    void amzRender() {
        nmMain();
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
